const body = $input.first().json.body ?? {};
const name = String(body.name ?? '').trim();
const email = String(body.email ?? '').trim();
const message = String(body.message ?? '').trim();
const source = String(body.source ?? 'unknown').trim().slice(0,80);
if (!name || !email || !message) {
  return [{ json: { ok: false, error: 'name, email, and message are required' } }];
}
if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
  return [{ json: { ok: false, error: 'Invalid email format' } }];
}
const lower = message.toLowerCase();
const priority = /urgent|asap|immediately|emergency/.test(lower) ? 'high' : 'normal';
const topic = /website|shopify|wordpress/.test(lower) ? 'website' : /automation|workflow|integrat/.test(lower) ? 'automation' : 'general';
return [{ json: { ok: true, lead: { name: name.slice(0,120), email: email.slice(0,254), message: message.slice(0,5000), source, topic, priority, receivedAt: new Date().toISOString() } } }];
